def transform(grid):
    out=[r[:] for r in grid]
    rows=[i for i,r in enumerate(grid) if 2 in r]
    if rows:
        boundary=max(rows,key=lambda i:grid[i].count(2))
        for i in range(boundary+1,len(grid)):
            out[i]=[0]*len(grid[i])
    return out

